import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame.")
    if 'group' not in df.columns and 'date' not in df.columns and 'value' not in df.columns:
        raise ValueError("DataFrame lacks required columns.")
    if 'date' not in df.columns or 'value' not in df.columns:
        raise ValueError("DataFrame must contain 'date' and 'value' columns.")
    if not pd.api.types.is_numeric_dtype(df['value']):
        raise ValueError("'value' column must be numeric.")
    if not isinstance(freq, str):
        raise ValueError("'freq' must be a valid frequency string.")
    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError("'decomposition_model' must be 'additive' or 'multiplicative'.")

    try:
        df = df.copy()
        df['date'] = pd.to_datetime(df['date'])
        df = df.set_index('date')
        series = df['value'].asfreq(freq)
    except Exception as e:
        raise ValueError(f"Invalid data or frequency: {e}")

    try:
        decomposition = seasonal_decompose(series, model=decomposition_model)
    except Exception as e:
        raise ValueError(f"Decomposition failed: {e}")

    fig, ax = plt.subplots(figsize=(10, 8))
    decomposition.plot()
    ax = plt.gca()

    return decomposition, ax

